package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();s.persist(new Employee(1,"Meenakshi",new Passport(101,"P1234567")));t.commit();System.out.println("Employee and passport persisted with cascade.");}HibernateUtil.getSessionFactory().close();}}